  try {
    const raw = localStorage.getItem(appearanceKey);
    const saved = raw && raw.length <= 512 ? JSON.parse(raw) : null;
    if (saved && typeof saved === 'object' && !Array.isArray(saved)) {
      if (typeof saved.name === 'string' && saved.name.trim().length > 0 && saved.name.length <= 32) appearance.name = saved.name.trim();
      if (typeof saved.icon === 'string' && saved.icon.trim().length > 0 && saved.icon.length <= 8) appearance.icon = saved.icon.trim();
      if (appearance.name) { el('zot-name').textContent = appearance.name; el('rename-zot').setAttribute('aria-label','修改 ' + appearance.name + ' 的显示名称'); el('zot-emblem').setAttribute('aria-label','编辑 ' + appearance.name + ' 图标'); }
      if (appearance.icon) el('zot-emblem').textContent = appearance.icon;
    }
  } catch {}

  let selectedItems = null, hasReadSession = false;
  const statusNames = {proposed:'待开始',running:'进行中',needs_input:'待决定',completed:'已完成',failed:'遇到问题',cancelled:'已取消'};
  const make = (tag, text, cls) => { const node=document.createElement(tag); if (text !== undefined) node.textContent=text; if(cls) node.className=cls; return node; };
  const empty = text => { const p = document.createElement('p'); p.className = 'empty'; p.textContent = text; items.replaceChildren(p); };

  function switchView(view) {
    for (const name of ['tasks','activity','capabilities']) { el(name+'-view').hidden = name !== view; el('view-'+name).setAttribute('aria-pressed',String(name===view)); }
  }
  function capabilityIcon(kind) {
    const box=make('span',undefined,'capability-icon');
    const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
    svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');
    const path=document.createElementNS('http://www.w3.org/2000/svg','path');
    path.setAttribute('d',({source:'M12 3l8 4v6c0 4-8 8-8 8s-8-4-8-8V7z M8 12l3 3 5-6',tasks:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',channel:'M4 5h16v12H9l-5 4z M8 9h8 M8 13h5',tools:'M6 3v18 M18 3v18 M3 8h6 M15 16h6'})[kind]);svg.append(path);box.append(svg);return box;
  }
  let detailOpener=null;
  function openDetail(title,paragraphs,opener){detailOpener=opener;el('detail-title').textContent=title;el('detail-content').replaceChildren(...paragraphs.filter(Boolean).map(text=>make('p',text)));el('detail-dialog').showModal();el('detail-close').focus();}
  function closeDetail(){el('detail-dialog').close();el('detail-content').replaceChildren();el('detail-title').textContent='';detailOpener?.focus();detailOpener=null;}
  el('detail-close').addEventListener('click',closeDetail);
