      const warning=make('p','上次快照可能已过期 · 本次更新失败','snapshot-warning');warning.hidden=true;sourceWarnings.push(warning);card.append(top,warning,body);el('canvas').insertBefore(card,el('add-column'));sourceCards.push(card);
