    clearSourceCards(); items.replaceChildren(); selectedItems=null; el('task-metrics').hidden=true; el('task-toolbar').hidden=true; el('task-distribution').hidden=true; el('activity-list').replaceChildren(make('p','等待读取所选任务','empty'));
