    el('business-remaining').textContent=Number.isFinite(b.remaining_ms)&&b.remaining_ms>=0?String(Math.ceil(b.remaining_ms/60000))+' 分钟':'待确认';
    el('business-used').textContent=Number.isFinite(b.used_ms)&&b.used_ms>=0?'已用 '+Math.floor(b.used_ms/60000)+' 分 '+Math.floor((b.used_ms%60000)/1000)+' 秒':'';
